'use strict';

var setPrototypeOf = require('setprototypeof');

/**
 * Set the prototype (i.e. [[Prototype]] / __proto__) of `object` to `prototype`.
 * Works across engines by preferring Object.setPrototypeOf and falling back to
 * the mutable __proto__ accessor.
 *
 * @param {object} object
 * @param {object|null} prototype
 * @returns {object} the same object
 */

module.exports = function setPrototype(object, prototype) {
  if (object === null || (typeof object !== 'object' && typeof object !== 'function')) {
    throw new TypeError('setPrototype requires an object');
  }
  return setPrototypeOf(object, prototype);
};
```

